Inductive sbase : Type :=
| SBLit
| SBVar (n : nat).

Definition sbase_eqb (b1 b2 : sbase) : bool :=
  match b1, b2 with
  | SBLit, SBLit => true
  | SBVar n, SBVar m => Nat.eqb n m
  | _, _ => false
  end.

Lemma sbase_eqb_eq : forall b1 b2, sbase_eqb b1 b2 = true -> b1 = b2.
Proof.
